def get_median(arr1, arr2, n):
    # Merge the two sorted arrays
    merged = []
    i = j = 0
    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1
    # Append remaining elements
    while i < n:
        merged.append(arr1[i])
        i += 1
    while j < n:
        merged.append(arr2[j])
        j += 1

    # Calculate median
    mid = n * 2 // 2
    if mid % 2 == 1:
        return float(merged[mid])
    else:
        return (merged[mid - 1] + merged[mid]) / 2.0
