def min_Swaps(s1, s2):
    # If lengths differ, conversion is impossible
    if len(s1) != len(s2):
        return "Not Possible"

    # Count positions where s1 has '1' and s2 has '0' (need to move 1 from s1 to s2)
    # and where s1 has '0' and s2 has '1' (need to move 1 from s2 to s1)
    diff_1_to_0 = 0  # s1[i] == '1' and s2[i] == '0'
    diff_0_to_1 = 0  # s1[i] == '0' and s2[i] == '1'

    for c1, c2 in zip(s1, s2):
        if c1 != c2:
            if c1 == '1':
                diff_1_to_0 += 1
            else:
                diff_0_to_1 += 1

    # If the number of mismatches is odd, it's impossible to balance
    if (diff_1_to_0 + diff_0_to_1) % 2 != 0:
        return "Not Possible"

    # Each swap can fix two mismatches (one of each type)
    return (diff_1_to_0 + diff_0_to_1) // 2
