def rgb_to_hsv(r, g, b):
    # Normalize RGB values to the range [0, 1]
    r, g, b = r / 255.0, g / 255.0, b / 255.0

    # Find max and min of RGB values
    cmax = max(r, g, b)
    cmin = min(r, g, b)
    delta = cmax - cmin

    # Calculate Value (V)
    v = cmax

    # Calculate Saturation (S)
    if delta == 0:
        s = 0.0
    else:
        s = delta / cmax

    # Calculate Hue (H)
    if delta == 0:
        h = 0.0
    else:
        if cmax == r:
            h = 60 * (((g - b) / delta) % 6)
        elif cmax == g:
            h = 60 * (((b - r) / delta) + 2)
        else:
            h = 60 * (((r - g) / delta) + 4)

    # Convert H to degrees (0-360), S and V to percentages (0-100)
    h = h % 360
    s = s * 100
    v = v * 100

    return (h, s, v)
