def last(arr, x, n):
    # Binary search for the last occurrence of x in sorted array arr[0..n-1]
    low, high = 0, n - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            result = mid
            low = mid + 1  # Try to find a later occurrence
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result
