def is_abundant(n):
    if n <= 1:
        return False

    # Sum of proper divisors
    divisor_sum = 1  # 1 is always a divisor for n > 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            divisor_sum += i
            # Add the pair divisor if it's different from i and not equal to n
            if i != n // i and n // i != n:
                divisor_sum += n // i
        i += 1

    # A number is abundant if the sum of its proper divisors is greater than the number itself
    return divisor_sum > n
```

