def join_tuples(tuples_list):
    if not tuples_list:
        return []

    # Group tuples by their first element
    groups = {}
    for t in tuples_list:
        first = t[0]
        if first not in groups:
            groups[first] = []
        groups[first].append(t)

    # Join tuples within each group
    result = []
    for first, group in groups.items():
        # Sort the group by the second element to ensure consistent ordering
        group.sort(key=lambda x: x[1])
        joined = (first,) + tuple(t[1] for t in group)
        result.append(joined)

    return result
```

def min_sum_path(triangle):
    if not triangle:
        return 0

    # Start from the second to last row and move upwards
    for i in range(len(triangle) - 2, -1, -1):
        for j in range(len(triangle[i])):
            # Add the minimum of the two possible paths from the current position
            triangle[i][j] += min(triangle[i + 1][j], triangle[i + 1][j + 1])

    # The top element now contains the minimum path sum
    return triangle[0][0]
```
